App.v6Scene=function(kind,title,sub,view){return `<button class="v6-scene" onclick="App.go('${view}')"><span class="v6-scene-art">${App.v6Art(kind)}</span><span><b>${title}</b><span>${sub}</span></span></button>`};
App.v6Visual=function(){const d=App.state||{},s=d.state||{},c=s.career||{};const map={dashboard:['business','Economic control','Capital, career, business and market in one view'],career:['job','Career path','Jobs, skills, interviews'],business:['business','Business studio','Operations, products, branches'],operations:['news','Risk desk','Incidents, damage and recovery'],finance:['invest','Finance room','Cash flow, debt and valuation'],market:['market','Market board','Assets, pricing and trading'],portfolio:['invest','Portfolio room','Allocation and performance'],people:['character','People desk','Employees, customers and performance'],suppliers:['food','Supply network','Suppliers, inventory and contracts'],events:['news','Decision feed','Events, consequences and history'],calendar:['interview','Planning desk','Interviews, meetings and deadlines'],profile:['character','Player profile','Identity, security and settings']};const m=map[App.view]||map.dashboard;return `<div class="v6-world"><div class="v6-art">${App.v6Art(m[0])}<span class="v6-art-label">${m[1]}</span></div><div class="v6-command-side"><div class="v6-side-title">Current simulation</div><div class="v6-side-value">Day ${s.day||1}</div><div class="v6-mini-grid"><div class="v6-mini"><b>${App.money(s.cash)}</b><span>Personal cash</span></div><div class="v6-mini"><b>${c.status==='employed'?App.money(c.salary):'—'}</b><span>Monthly salary</span></div><div class="v6-mini"><b>${(d.businesses||[]).length}</b><span>Businesses</span></div><div class="v6-mini"><b>${App.num(s.reputation||0)}</b><span>Reputation</span></div></div></div></div><div class="v6-rail">${App.v6Scene('character','Characters','Employees, investors, HR','people')}${App.v6Scene('food','Products','Food & retail products','business')}${App.v6Scene('drink','Services','Food, beverage & service','business')}${App.v6Scene('land','Property','Land & property assets','market')}${App.v6Scene('news','News','Economic & business events','events')}</div>`};
App.v6ShellRender=function(){const d=App.state,s=d.state,biz=d.businesses||[],title=(App.navItems.find(x=>x[0]===App.view)||['','BizSim'])[1];document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${App.icon('chart',19)}</div><div><strong>BizSim</strong><small>v6.1 · Economic Life</small></div></div>${App.navItems.map(x=>`<button class="nav-item ${App.view===x[0]?'active':''}" onclick="App.go('${x[0]}')"><span class="nav-icon">${App.icon(x[2],17)}</span>${x[1]}</button>`).join('')}<div class="nav-label">Account</div><button class="nav-item ${App.view==='profile'?'active':''}" onclick="App.go('profile')"><span class="nav-icon">${App.icon('users',17)}</span>Profile</button><button class="nav-item" onclick="App.logout()"><span class="nav-icon">${App.icon('arrow',17)}</span>Keluar</button><div class="sidebar-footer">Storage: server<br>Source of truth: server<br>Build: 6.0.0</div></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="icon-btn menu-mobile" onclick="App.toggleSidebar()" aria-label="Open navigation">${App.icon('menu',17)}</button><div><b>${esc(title)}</b><div class="crumb">BizSim 6.0 / ${esc(title)}</div></div></div><div class="top-actions"><button class="icon-btn" onclick="App.refresh()" title="Refresh">${App.icon('refresh',17)}</button><button class="icon-btn" onclick="App.openNotifications()" title="Notifications">${App.icon('bell',17)}</button><div class="avatar">${esc((d.user.name||'P').slice(0,1).toUpperCase())}</div></div></header><section class="content v6-view"><div class="v6-command"><div class="v6-command-main"><div class="v6-kicker">BizSim 6.0 / ${esc(title)}</div><h1>${App.view==='dashboard'?'Bangun ekonomi dari nol, lalu kelola konsekuensinya.':esc(title)}</h1><p>${App.view==='dashboard'?'Career, pekerjaan, bisnis, investasi, pasar, risiko, karakter, dan keputusan berjalan di atas state server yang sama.':`Workspace ${esc(title)} dengan data yang berasal dari simulation state server.`}</p><div class="v6-command-actions"><button class="btn primary" onclick="App.simDay()">${App.icon('refresh',14)} Simulate Day</button><button class="btn" onclick="App.go('career')">Career</button><button class="btn" onclick="App.go('investments')">Investments</button></div></div><div class="v6-command-side"><div class="v6-side-title">Economic snapshot</div><div class="v6-side-value">${App.money(s.cash)}</div><div class="v6-mini-grid"><div class="v6-mini"><b>${App.money((biz||[]).reduce((a,x)=>a+(x.value||0),0))}</b><span>Business value</span></div><div class="v6-mini"><b>${(d.incidents||[]).filter(x=>x.status==='active').length}</b><span>Active incidents</span></div><div class="v6-mini"><b>${(d.transactions||[]).length}</b><span>Transactions</span></div><div class="v6-mini"><b>${s.credit_score||0}</b><span>Credit score</span></div></div></div></div>${App.v6Visual()}${App.page()}</section></main></div><nav class="mobile-nav">${App.navItems.slice(0,5).map(x=>`<button class="${App.view===x[0]?'active':''}" onclick="App.go('${x[0]}')"><span class="nav-icon">${App.icon(x[2],18)}</span>${x[1].split(' ')[0]}</button>`).join('')}</nav>`};
App.render=App.v6ShellRender;
// Realistic investor discovery: create an offer from business metrics, not a static free-money popup.
App.openInvestor=async id=>{if(!id)return App.toast('Business belum tersedia','Buat bisnis terlebih dahulu.','warning');App.modal('Investor discovery',`<div class="detail-grid"><div class="detail"><span>Process</span><b>Business screening</b></div><div class="detail"><span>Basis</span><b>Revenue · profit · risk · reputation</b></div><div class="detail"><span>Outcome</span><b>Offer may be created or declined</b></div><div class="detail"><span>Ownership</span><b>Equity is negotiated</b></div></div><div class="notice" style="margin-top:14px">Investor tidak menghasilkan modal gratis. Offer dihitung dari kondisi bisnis, valuasi tersirat, risiko, dan kemampuan growth.</div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="App.discoverInvestor(${id})">Run Investor Screening</button>`)};
App.discoverInvestor=async id=>{const r=await App.request('/api/investors/discover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({businessId:id})});const d=await r.json();if(!r.ok)return App.toast('Investor tidak masuk',d.error||'Business belum memenuhi screening.','warning');closeModal();await App.refresh();App.openInvestorOffer(d.id)};
App.openInvestorOffer=id=>{const o=(App.state.investors||[]).find(x=>x.id===id);if(!o)return;const t=JSON.parse(o.terms_json||'{}');App.modal('Investment Offer',`<div class="v6-invest-hero"><div>${App.v6Art('invest')}</div><div><div class="v6-kicker">Investor offer</div><h2 style="margin:5px 0">${esc(o.name)}</h2><p class="muted" style="margin:0">${esc(o.type)} · Risk ${esc(o.risk)}</p></div></div><div class="detail-grid" style="margin-top:14px"><div class="detail"><span>Investment</span><b>${App.money(o.investment)}</b></div><div class="detail"><span>Requested equity</span><b>${o.equity}%</b></div><div class="detail"><span>Implied valuation</span><b>${App.money(t.valuation||0)}</b></div><div class="detail"><span>Expected growth</span><b>${o.growth}%</b></div><div class="detail"><span>Voting rights</span><b>${t.voting?'Possible':'No'}</b></div><div class="detail"><span>Exit clause</span><b>${esc(t.exit||'Negotiable')}</b></div></div>`,`<button class="btn danger" onclick="App.investDecision(${o.id},'reject')">Reject</button><button class="btn" onclick="App.openNegotiation(${o.id})">Negotiate</button><button class="btn success" onclick="App.investDecision(${o.id},'accept')">Accept</button>`) };
App.openNegotiation=id=>{const o=(App.state.investors||[]).find(x=>x.id===id);if(!o)return;closeModal();App.modal('Investor negotiation',`<div class="notice">Counter offer dinilai terhadap business valuation dan risk. Investor dapat menolak terms yang terlalu jauh.</div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Investment (IDR)</label><input id="offer-invest" type="number" value="${o.investment}" min="1000000"></div><div class="field"><label>Requested Equity (%)</label><input id="offer-equity" type="number" value="${o.equity}" min="1" max="60" step="0.1"></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="App.investCounter(${id})">Send Counter</button>`)};
App.investCounter=async id=>{const r=await App.request('/api/investors/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action:'counter',investment:Number(document.getElementById('offer-invest').value),equity:Number(document.getElementById('offer-equity').value)})});const d=await r.json();if(!r.ok)return App.toast('Counter ditolak',d.error||'Investor menolak terms.','warning');closeModal();App.toast('Counter accepted for review',`Score ${d.counterScore}. Offer tetap menunggu keputusan final.`, 'info');await App.refresh()};

/* Incremental UX + simulation patch: keeps the existing BizSim renderer and feature modules. */
(() => {
  App.navItems = [
    ['dashboard','Dashboard','home'],['career','Career & Jobs','briefcase'],['business','Business','box'],
    ['operations','Operations & Risk','shield'],['finance','Finance','wallet'],['market','Asset Market','trend'],
    ['investments','Investments','chart'],['portfolio','Portfolio','chart'],['people','Employees & Customers','users'],
    ['suppliers','Suppliers','globe'],['events','Events & Decisions','bell'],['calendar','Calendar & Tasks','calendar']
  ];

  App.image = (path, alt='') => `<img class="feature-image" src="/assets/images/${path}" alt="${esc(alt)}" loading="lazy">`;
  App.marketSpark = (history) => {
    const vals=(history||[]).map(Number).filter(Number.isFinite);
    if(vals.length<2) return '<div class="market-empty-chart">Menunggu data pasar</div>';
    const min=Math.min(...vals), max=Math.max(...vals), range=max-min||1;
    const pts=vals.map((v,i)=>`${(i/(vals.length-1))*420},${132-((v-min)/range)*105}`).join(' ');
    const last=vals[vals.length-1], prev=vals[vals.length-2], up=last>=prev;
    return `<div class="market-chart"><svg viewBox="0 0 420 150" preserveAspectRatio="none" aria-label="Grafik harga simulasi"><path class="grid-line" d="M0 132H420"/><polyline class="market-line ${up?'up':'down'}" points="${pts}"/></svg><span class="chart-end ${up?'up':'down'}">${up?'▲':'▼'} ${Math.abs(((last-prev)/prev)*100).toFixed(2)}%</span></div>`;
  };

  App.loadCatalogs = async () => {
    const [jobs,biz,inv] = await Promise.all([
      App.requestJson('/api/jobs'), App.requestJson('/api/businesses/catalog'), App.requestJson('/api/investments/catalog')
    ]);
    App._jobs=jobs.d.jobs||[]; App.businessCatalog=biz.d.businesses||[]; App.investmentCatalog=inv.d.investments||[];
  };

  App.init = async () => {
    try {
      const {r,d}=await App.requestJson('/api/me');
      if(r.ok&&d.user){App.hydrate(d);await App.loadCatalogs();App.render();}
      else App.renderAuth();
    } catch(e) { console.error(e); App.renderAuth(); App.toast('Koneksi gagal','Server BizSim tidak dapat dihubungi.','danger'); }
  };
  App.refresh = async () => {
    const r=await App.request('/api/me');
    if(!r.ok) return;
    App.hydrate(await r.json());
    await App.loadCatalogs();
    App.render();
  };

  App.career = () => {
    const c=App.state.state.career||{}, skills=App.state.state.skills||{}, creator=(App.state.creators||[])[0];
    return `<div class="page-head"><div><h1>Career</h1><p>Pekerjaan adalah jalur penghasilan utama. YouTube tersedia sebagai side income, bukan bisnis.</p></div><div class="actions"><button class="btn" onclick="App.openSkillTraining()">Training</button><button class="btn primary" onclick="App.openEducation()">Education</button></div></div>
      <div class="grid two">
        <div class="card"><div class="section-head"><div><h3 class="section-title">Current Career</h3><span class="small muted">Penghasilan utama</span></div><span class="badge ${c.status==='employed'?'success':'warn'}">${c.status==='employed'?'Employed':'Unemployed'}</span></div>
          <div class="career-hero">${App.image('features/career.svg','Career')}<div><b>${esc(c.position||'Belum bekerja')}</b><p>${esc(c.company||'Pilih pekerjaan untuk memulai.')}</p><strong>${App.money(c.salary||0)} <small>/ bulan</small></strong></div></div>
          <div class="detail-grid" style="margin-top:14px"><div class="detail"><span>Experience</span><b>${c.experience||0} bulan</b></div><div class="detail"><span>Reputation</span><b>${Math.round(App.state.state.reputation||0)}</b></div></div>
          <div style="margin-top:14px">${Object.entries(skills).slice(0,8).map(([k,v])=>`<div class="metric-row"><span>${esc(k)}</span><div style="width:48%"><div class="progress"><i style="width:${Math.min(100,v)}%"></i></div></div><b>${Math.round(v)}</b></div>`).join('')}</div>
        </div>
        <div class="card"><div class="section-head"><div><h3 class="section-title">YouTube Side Income</h3><span class="small muted">Jalur karier tambahan</span></div><span class="badge blue">Optional</span></div>
          ${creator?`<div class="career-hero">${App.image('features/youtube.svg','YouTube')}<div><b>${esc(creator.name)}</b><p>${esc(creator.niche)} · ${creator.subscribers.toLocaleString('id-ID')} subscribers</p><strong>${App.money(creator.income)} <small>lifetime income</small></strong></div></div><div class="detail-grid" style="margin-top:14px"><div class="detail"><span>Views</span><b>${creator.views.toLocaleString('id-ID')}</b></div><div class="detail"><span>Monetization</span><b>${creator.monetized?'Active':'Building'}</b></div></div><button class="btn accent" style="width:100%;margin-top:14px" onclick="App.openYoutubeCareer()">Manage Channel</button>`:`<div class="empty-visual">${App.image('features/youtube.svg','YouTube')}<p>Bangun channel untuk menambah penghasilan di luar gaji tanpa membuka bisnis.</p><button class="btn accent" onclick="App.openYoutubeCareer()">Start YouTube</button></div>`}
        </div>
      </div>
      <div class="card" style="margin-top:16px"><div class="section-head"><div><h3 class="section-title">Job Market</h3><span class="small muted">Skill dan pendidikan memengaruhi hasil interview</span></div><span class="badge blue">${App.jobs().length} openings</span></div><div class="job-grid">${App.jobs().map(j=>`<article class="job-card">${App.image('features/career.svg','Job')}<div class="job-card-body"><b>${esc(j.title)}</b><span>${esc(j.company)} · ${esc(j.industry)}</span><strong>${App.money(j.salary)}<small>/bulan</small></strong><div class="job-requirements"><span>Skill ${j.min_skill}+</span><span>${esc(j.education)}</span></div><button class="btn accent" onclick="App.applyJob('${esc(j.id)}')">Apply & Interview</button></div></article>`).join('')||'<div class="empty">Job market belum tersedia.</div>'}</div></div>
      <div class="card" style="margin-top:16px"><div class="section-head"><h3 class="section-title">Work History</h3></div>${(c.history||[]).map(h=>`<div class="timeline-item"><b>${esc(h.position)} · ${esc(h.company)}</b><p>${App.money(h.salary)}/month · day ${h.startedDay}</p></div>`).join('')||'<div class="empty">Belum ada work history.</div>'}</div>`;
  };

  App.business = () => {
    const b=App.state.businesses||[], skills=App.state.state.skills||{};
    return `<div class="page-head"><div><h1>Business</h1><p>12 bisnis sudah tersedia. Modal, skill, dan kemampuan operasional menentukan bisnis yang bisa dibuka.</p></div><button class="btn" onclick="App.openLoan()">Business Loan</button></div>
      ${b.length?`<div class="section-head"><div><h3 class="section-title">My Businesses</h3><span class="small muted">${b.length} bisnis aktif</span></div></div><div class="grid three">${b.map(x=>`<article class="card business-owned">${App.image(`business/${x.catalogId||'warung'}.svg`,x.name)}<div class="section-head" style="margin-top:12px"><div><h3 class="section-title">${esc(x.name)}</h3><span class="small muted">${esc(x.type)} · ${esc(x.location)}</span></div><span class="badge blue">${App.money(x.value)}</span></div><div class="metric-row"><span>Cash</span><b>${App.money(x.cash)}</b></div><div class="metric-row"><span>Revenue</span><b>${App.money(x.revenue)}</b></div><div class="metric-row"><span>Expenses</span><b>${App.money(x.expenses)}</b></div><div class="actions" style="margin-top:12px"><button class="btn" onclick="App.createIncident(${x.id})">Incident</button><button class="btn accent" onclick="App.openInvestor(${x.id})">Investor</button></div></article>`).join('')}</div>`:''}
      <div class="section-head" style="margin-top:24px"><div><h3 class="section-title">Business Catalog</h3><span class="small muted">12 pilihan dari usaha kecil sampai manufaktur</span></div></div>
      <div class="business-catalog">${App.businessCatalog.map(x=>{const have=Number(skills[x.skill]||0),cash=Number(App.state.state.cash),canCash=cash>=x.startup,canSkill=have>=x.minSkill,ok=canCash&&canSkill;return `<article class="business-card ${ok?'available':'locked'}">${App.image(`business/${x.image}`,x.name)}<div class="business-card-body"><div class="section-head"><div><h3>${esc(x.name)}</h3><span>${esc(x.category)}</span></div><span class="badge ${ok?'success':'warn'}">${ok?'Available':'Locked'}</span></div><p>${esc(x.description)}</p><div class="business-price"><span>Modal awal</span><strong>${App.money(x.startup)}</strong></div><div class="business-req"><span>Skill ${esc(x.skill)}</span><b>${Math.round(have)} / ${x.minSkill}</b></div><div class="progress"><i style="width:${Math.min(100,have/x.minSkill*100)}%"></i></div><div class="business-card-foot"><span>${canCash?'Cash cukup':'Butuh '+App.money(x.startup-cash)+' lagi'}</span><button class="btn primary" ${ok?'':'disabled'} onclick="App.openCreateBusiness('${x.id}')">Open Business</button></div></div></article>`}).join('')}</div>`;
  };

  App.marketPage = () => {
    const m=App.state.state.market||{}, prices=m.prices||{}, history=m.history||{}, hold=App.state.state.portfolio?.holdings||{};
    return `<div class="page-head"><div><h1>Asset Market</h1><p>Trading market simulasi. Harga bergerak random dari server, sehingga posisi bisa profit maupun loss.</p></div><span class="badge blue">SIMULATED · ${esc(m.sentiment||'neutral')}</span></div>
      <div class="market-notice">${App.image('features/market.svg','Market')}<div><b>Trading, bukan investasi jangka panjang</b><p>BTC dan saham simulasi bergerak per market tick. Harga beli, fee, holding, dan P/L disimpan di server.</p></div></div>
      <div class="grid three">${['BTC','BBCA','TLKM'].map(a=>{const p=prices[a]||0,h=history[a]||[],prev=h.length>1?h[h.length-2]:p,ch=prev?((p-prev)/prev)*100:0,q=Number(hold[a]||0),cost=Number(App.state.state.portfolio?.costBasis?.[a]||0),value=q*p,pnl=value-cost;return `<article class="card market-card"><div class="section-head"><div><h3 class="section-title">${a}</h3><span class="small muted">${a==='BTC'?'Crypto':'Saham simulasi'}</span></div><span class="market-change ${ch>=0?'up':'down'}">${ch>=0?'+':''}${ch.toFixed(2)}%</span></div><div class="market-price">${App.money(p)}</div>${App.marketSpark(h)}<div class="market-meta"><span>Holding <b>${q}</b></span><span class="${pnl>=0?'positive':'negative'}">P/L ${pnl>=0?'+':''}${App.money(pnl)}</span></div><button class="btn accent" style="width:100%;margin-top:12px" onclick="App.openTrade('${a}',${p})">Trade</button></article>`}).join('')}</div>
      <div class="card" style="margin-top:16px"><div class="section-head"><div><h3 class="section-title">Market Engine</h3><span class="small muted">Random walk dengan volatilitas berbeda</span></div><button class="btn" onclick="App.marketTickNow()">Next Market Tick</button></div><div class="detail-grid"><div class="detail"><span>BTC</span><b>Volatilitas tinggi</b></div><div class="detail"><span>BBCA / TLKM</span><b>Volatilitas sedang</b></div><div class="detail"><span>Fee</span><b>0,25%</b></div><div class="detail"><span>Source</span><b>Server simulation</b></div></div></div>`;
  };

  App.page = () => {switch(App.view){case'dashboard':return App.dashboard();case'career':return App.career();case'business':return App.business();case'operations':return App.operations();case'finance':return App.finance();case'market':return App.marketPage();case'investments':return App.investments();case'portfolio':return App.portfolio();case'people':return App.people();case'suppliers':return App.suppliers();case'events':return App.events();case'calendar':return App.calendar();case'profile':return App.profile();default:return App.dashboard();}};

  App.investments = () => {
    const inv=App.state.state.investments||[];
    return `<div class="page-head"><div><h1>Investments</h1><p>Instrumen jangka panjang dipisahkan dari Asset Market: saham, emas, tanah, properti, dan obligasi.</p></div></div><div class="grid three">${App.investmentCatalog.map(x=>`<article class="card investment-card">${App.image(`investments/${x.image}`,x.name)}<div class="section-head" style="margin-top:12px"><div><h3 class="section-title">${esc(x.name)}</h3><span class="small muted">${esc(x.category)}</span></div><span class="badge blue">Long term</span></div><p class="small muted">${esc(x.description)}</p><div class="metric-row"><span>Minimum</span><b>${App.money(x.minimum)}</b></div><button class="btn primary" style="width:100%;margin-top:10px" onclick="App.openInvestment('${x.id}')">Invest</button></article>`).join('')}</div><div class="card" style="margin-top:16px"><div class="section-head"><h3 class="section-title">My Investments</h3></div>${inv.map(x=>`<div class="list-item"><div><div class="title">${esc(x.name)}</div><div class="meta">${esc(x.category)} · invested ${App.money(x.invested)}</div></div><div style="text-align:right"><b class="${x.currentValue>=x.invested?'positive':'negative'}">${App.money(x.currentValue)}</b><br><button class="btn" onclick="App.sellInvestment('${x.id}')">Sell</button></div></div>`).join('')||'<div class="empty">Belum ada investasi.</div>'}</div>`;
  };

  App.openCreateBusiness = (catalogId) => {
    const x=App.businessCatalog.find(v=>v.id===catalogId); if(!x)return;
    const skill=Number(App.state.state.skills?.[x.skill]||0), ok=Number(App.state.state.cash)>=x.startup&&skill>=x.minSkill;
    App.modal(x.name,`${App.image(`business/${x.image}`,x.name)}<div class="detail-grid" style="margin-top:14px"><div class="detail"><span>Modal</span><b>${App.money(x.startup)}</b></div><div class="detail"><span>Skill</span><b>${esc(x.skill)} ${Math.round(skill)}/${x.minSkill}</b></div><div class="detail"><span>Fixed cost</span><b>${App.money(x.monthlyFixed)}/bulan</b></div><div class="detail"><span>Category</span><b>${esc(x.category)}</b></div></div><div class="field" style="margin-top:14px"><label>Nama bisnis</label><input id="biz-name" value="${esc(x.name)}"></div><div class="field" style="margin-top:10px"><label>Location</label><select id="biz-location"><option>Jakarta Selatan</option><option>Bandung</option><option>Surabaya</option><option>Yogyakarta</option><option>Malang</option></select></div>${ok?'':'<div class="notice danger" style="margin-top:12px">Penuhi modal dan skill terlebih dahulu.</div>'}`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" ${ok?'':'disabled'} onclick="App.createBusinessSubmit('${x.id}')">Open Business</button>`);
  };
  App.createBusinessSubmit = async (catalogId) => {
    const r=await App.request('/api/businesses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({catalogId,name:document.getElementById('biz-name').value,location:document.getElementById('biz-location').value})});
    const d=await r.json(); if(!r.ok)return App.toast('Business gagal dibuat',d.error||'','danger'); closeModal(); await App.refresh();
  };

  App.openYoutubeCareer = () => {
    const c=App.state.creators?.[0];
    if(!c){App.modal('Start YouTube Career',`${App.image('features/youtube.svg','YouTube')}<p class="small muted">YouTube adalah side income. Tidak ada modal bisnis; progres ditentukan oleh kualitas, editing, audience, dan konsistensi.</p><div class="form-grid"><div class="field"><label>Channel name</label><input id="yt-name" value="${esc(App.user.name)} Channel"></div><div class="field"><label>Niche</label><select id="yt-niche"><option>Gaming</option><option>Education</option><option>Technology</option><option>Finance</option><option>Entertainment</option></select></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="App.createYoutube()">Start Channel</button>`)}
    else App.modal('YouTube Career',`${App.image('features/youtube.svg','YouTube')}<div class="detail-grid" style="margin-top:12px"><div class="detail"><span>Subscribers</span><b>${c.subscribers.toLocaleString('id-ID')}</b></div><div class="detail"><span>Views</span><b>${c.views.toLocaleString('id-ID')}</b></div><div class="detail"><span>Watch hours</span><b>${Math.round(c.watch_hours).toLocaleString('id-ID')}</b></div><div class="detail"><span>Monetization</span><b>${c.monetized?'Active':'Building'}</b></div></div>`,`<button class="btn" onclick="closeModal()">Close</button><button class="btn accent" onclick="App.publishYoutube()">Publish Video</button>`);
  };
  App.createYoutube = async () => {const r=await App.request('/api/creators',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:document.getElementById('yt-name').value,niche:document.getElementById('yt-niche').value,quality:Math.min(100,Number(App.state.state.skills?.design||20)+10),editing:Math.min(100,Number(App.state.state.skills?.programming||20)+5)})});const d=await r.json();if(!r.ok)return App.toast('Channel gagal dibuat',d.error||'','danger');closeModal();await App.refresh();};
  App.publishYoutube = async () => {const c=App.state.creators?.[0];if(!c)return;const r=await App.request('/api/creators/publish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:c.id,trending:Math.random()<.15})});const d=await r.json();if(!r.ok)return App.toast('Publish gagal',d.error||'','danger');closeModal();App.toast('Video published',`+${d.views.toLocaleString('id-ID')} views · +${d.subscribers.toLocaleString('id-ID')} subscribers.`,'success');await App.refresh();};
  App.marketTickNow = async () => {const r=await App.request('/api/market/tick',{method:'POST'}),d=await r.json();if(!r.ok)return App.toast('Market tick gagal',d.error||'','danger');App.state.state.market={...App.state.state.market,prices:d.prices,history:d.history,sentiment:d.sentiment};App.render();};
  App.openTrade = (asset,price) => {const holding=Number(App.state.state.portfolio?.holdings?.[asset]||0);App.modal(`Trade ${asset}`,`${App.image('features/market.svg','Market')}<div class="detail-grid" style="margin-top:12px"><div class="detail"><span>Current price</span><b>${App.money(price)}</b></div><div class="detail"><span>Holding</span><b>${holding}</b></div><div class="detail"><span>Fee</span><b>0,25%</b></div><div class="detail"><span>Cash</span><b>${App.money(App.state.state.cash)}</b></div></div><div class="field" style="margin-top:14px"><label>Quantity</label><input id="trade-qty" type="number" min="0.0001" step="0.0001" value="0.01"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button>${holding>0?`<button class="btn" onclick="App.trade('${asset}',${price},'SELL')">Sell</button>`:''}<button class="btn primary" onclick="App.trade('${asset}',${price},'BUY')">Buy</button>`);};
  App.trade = async (asset,price,kind) => {const q=Number(document.getElementById('trade-qty').value);const r=await App.request('/api/market/transaction',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset,price,quantity:q,kind})});const d=await r.json();if(!r.ok)return App.toast('Transaction failed',d.error||'','danger');closeModal();App.toast(kind==='BUY'?'Position dibuka':'Position dikurangi',`${kind==='BUY'?'Buy':'Sell'} ${q} ${asset} @ ${App.money(d.price)} · fee ${App.money(d.fee)}`,'success');await App.refresh();};
  App.openInvestment = id => {const x=App.investmentCatalog.find(v=>v.id===id);if(!x)return;App.modal(x.name,`${App.image(`investments/${x.image}`,x.name)}<p class="small muted">${esc(x.description)}</p><div class="field"><label>Nominal investasi</label><input id="inv-amount" type="number" min="${x.minimum}" value="${x.minimum}"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="App.buyInvestment('${x.id}')">Invest</button>`);};
  App.buyInvestment = async id => {const r=await App.request('/api/investments/buy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:id,amount:Number(document.getElementById('inv-amount').value)})});const d=await r.json();if(!r.ok)return App.toast('Investasi gagal',d.error||'','danger');closeModal();await App.refresh();};
  App.sellInvestment = async id => {const r=await App.request('/api/investments/sell',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});const d=await r.json();if(!r.ok)return App.toast('Penjualan gagal',d.error||'','danger');await App.refresh();App.toast('Investasi dijual',`Realisasi ${App.money(d.realized)}.`,'success');};

  const addFeature = (fn, image, title) => {const old=App[fn];if(typeof old!=='function')return;App[fn]=()=>`<div class="feature-strip">${App.image(image,title)}<div><b>${title}</b><p>Data dan konsekuensi berasal dari simulation state server.</p></div></div>${old()}`;};
  addFeature('operations','features/operations.svg','Operations & Risk');
  addFeature('finance','features/investments.svg','Finance Control');
  addFeature('portfolio','features/market.svg','Portfolio Analytics');
  addFeature('people','features/people.svg','Employees & Customers');
  addFeature('suppliers','features/suppliers.svg','Suppliers');
  addFeature('events','features/events.svg','Events & Decisions');

  const oldRender=App.render;
  App.marketTimer=null;
  App.render=()=>{clearInterval(App.marketTimer);App.marketTimer=null;oldRender();if(App.view==='market'){App.marketTimer=setInterval(async()=>{try{const r=await App.request('/api/market/tick',{method:'POST'}),d=await r.json();if(r.ok){App.state.state.market={...App.state.state.market,prices:d.prices,history:d.history,sentiment:d.sentiment};oldRender();}}catch{}} ,7000);}};
})();

boot();
